package com.minimarket.proveedor.service; import com.minimarket.common.exception.*; import com.minimarket.proveedor.dto.*; import com.minimarket.proveedor.entity.Proveedor; import com.minimarket.proveedor.repository.ProveedorRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; @Service @RequiredArgsConstructor @Transactional(readOnly=true) public class ProveedorServiceImpl implements ProveedorService{private final ProveedorRepository r;public Page<ProveedorResponseDTO> listar(Pageable p){return r.findByActivoTrue(p).map(this::d);}public ProveedorResponseDTO obtener(Long id){return d(f(id));}public ProveedorResponseDTO porDocumento(String t,String n){return d(r.findByTipoDocumentoAndNumeroDocumento(t,n).orElseThrow(()->new ResourceNotFoundException("Proveedor no encontrado")));}@Transactional public ProveedorResponseDTO crear(ProveedorRequestDTO x){if(r.existsByTipoDocumentoAndNumeroDocumento(x.tipoDocumento(),x.numeroDocumento()))throw new BusinessException("Proveedor ya registrado");return d(r.save(Proveedor.builder().tipoDocumento(x.tipoDocumento().toUpperCase()).numeroDocumento(x.numeroDocumento().trim()).razonSocial(x.razonSocial().trim()).nombreComercial(x.nombreComercial()).direccion(x.direccion()).telefono(x.telefono()).email(x.email()).contactoNombre(x.contactoNombre()).activo(true).build()));}@Transactional public ProveedorResponseDTO actualizar(Long id,ProveedorRequestDTO x){Proveedor p=f(id);if(r.existsByTipoDocumentoAndNumeroDocumentoAndIdNot(x.tipoDocumento(),x.numeroDocumento(),id))throw new BusinessException("Proveedor ya registrado");p.setTipoDocumento(x.tipoDocumento().toUpperCase());p.setNumeroDocumento(x.numeroDocumento().trim());p.setRazonSocial(x.razonSocial().trim());p.setNombreComercial(x.nombreComercial());p.setDireccion(x.direccion());p.setTelefono(x.telefono());p.setEmail(x.email());p.setContactoNombre(x.contactoNombre());return d(p);}@Transactional public void desactivar(Long id){f(id).setActivo(false);}private Proveedor f(Long id){return r.findById(id).orElseThrow(()->ResourceNotFoundException.of("Proveedor",id));}private ProveedorResponseDTO d(Proveedor p){return new ProveedorResponseDTO(p.getId(),p.getTipoDocumento(),p.getNumeroDocumento(),p.getRazonSocial(),p.getNombreComercial(),p.getDireccion(),p.getTelefono(),p.getEmail(),p.getContactoNombre(),p.getActivo(),p.getCreatedAt());}}